function validateField(field){const wrapper=field.closest('.get-started-form-input-wrapper');if(!wrapper)return;let isValid=false;if(field.type==='email'){const emailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;isValid=emailPattern.test(field.value.trim())&&field.value.trim().length>0}else if(field.type==='tel'){const digitsOnly=field.value.replace(/\D/g,'');isValid=digitsOnly.length>=10}else if(field.tagName==='SELECT'){isValid=field.value!==''&&field.value!==null}else{isValid=field.value.trim().length>0}if(isValid){wrapper.classList.add('valid')}else{wrapper.classList.remove('valid')}}function initGetStartedForm(){const container=document.querySelector('.get-started-form-section')||document;const formFields=container.querySelectorAll('.get-started-form-input-wrapper input,.get-started-form-input-wrapper select');formFields.forEach(field=>{if(field.hasAttribute('data-form-initialized')){return}field.setAttribute('data-form-initialized','true');const wrapper=field.closest('.get-started-form-input-wrapper');field.addEventListener('focus',function(){const currentWrapper=this.closest('.get-started-form-input-wrapper');if(currentWrapper){currentWrapper.classList.add('focused')}});field.addEventListener('blur',function(){const currentWrapper=this.closest('.get-started-form-input-wrapper');if(currentWrapper){currentWrapper.classList.remove('focused');validateField(this)}});if(field.tagName==='SELECT'){field.addEventListener('change',function(){validateField(this)})}});const contactNumberField=container.querySelector('#contactNumber');if(contactNumberField&&!contactNumberField.hasAttribute('data-phone-initialized')){contactNumberField.setAttribute('data-phone-initialized','true');contactNumberField.addEventListener('input',function(e){const phonePattern=/[^0-9\s()\-+]/g;e.target.value=e.target.value.replace(phonePattern,'');validateField(e.target)});contactNumberField.addEventListener('paste',function(e){e.preventDefault();const pastedText=(e.clipboardData||window.clipboardData).getData('text');const cleanedText=pastedText.replace(/[^0-9\s()\-+]/g,'');const start=e.target.selectionStart;const end=e.target.selectionEnd;e.target.value=e.target.value.substring(0,start)+cleanedText+e.target.value.substring(end);e.target.setSelectionRange(start+cleanedText.length,start+cleanedText.length);validateField(e.target)})}}document.addEventListener('DOMContentLoaded',function(){initGetStartedForm()});window.initGetStartedForm=initGetStartedForm;